// Where the game is. Set by the game; the launcher reads it to judge a heartbeat that stands.
enum class Phase : std::uint32_t
{
  None = 0,  // the game has not taken the board (yet)
  Starting = 1,  // the game took the board; no picture yet
  Offline = 2,  // a plain start: the game's own title, menus and races
  Loading = 3,  // a race's or replay's course loads
  Joining = 4,  // asking the relay for the seat
  Gate = 5,  // at the start gate until the relay's go: no game frame begins here, by design
  Countdown = 6,  // the race's countdown (lockstep)
  Racing = 7,  // the race runs and this game's racer races
  Finished = 8,  // this game's racer is over the line or out; the race and its results go on
  Playback = 9,  // a replay plays
  Left = 10,  // the game left its race (no inputs in time, a refused stat pack, a race already over)
  Stopping = 11,  // a stop was asked for; the game shuts down
};

// What asked the game to stop, first ask only (protocol/formats.md section 7 has the log's words for each).
enum class StopReason : std::uint32_t
{
  None = 0,  // no stop asked
  StripClose = 1,  // the close button of the game window's strip
  AltF4 = 2,  // Alt+F4
  SystemClose = 3,  // the system's close command (the window's menu, the taskbar)
  OutsideClose = 4,  // a close message from outside the window
  Escape = 5,  // Escape in the game's window
  Game = 6,  // the game itself (the results left, a desync, a replay's end, ...)
  Launcher = 7,  // the launcher, through the mailbox
  Unasked = 8,  // the emulator stopped with none of the above
};

// What an event of the ring says. A and B are each kind's own.
enum class EventKind : std::uint32_t
{
  None = 0,  // an empty slot
  Phase = 1,  // the phase changed: A the new one, B the one before
  Stop = 2,  // a stop was asked for: A its StopReason
  Stands = 3,  // the game's own freeze watch reports a freeze: A milliseconds stood, B the report's number
  Moves = 4,  // the game moves again after a reported freeze: A milliseconds it stood
  Notice = 5,  // the game took a notice from the mailbox: A its serial
  Desync = 6,  // a step's checksum differed from the relay's: A the step
};

// A racer at the snapshot's moment.
enum class RacerState : std::uint8_t
{
  Racing = 0,  // racing
  Finished = 1,  // over the line
  Out = 2,  // knocked out or retired, by the game's own test
};

// The status block's Flags.
inline constexpr std::uint32_t STATUS_FLAGS_WAITS_FOR_RELAY = 1;
inline constexpr std::uint32_t STATUS_FLAGS_PRACTICE = 2;
inline constexpr std::uint32_t STATUS_FLAGS_WATCHING = 4;
inline constexpr std::uint32_t STATUS_FLAGS_REJOIN = 8;

// A racer record's Flags.
inline constexpr std::uint8_t RACER_FLAGS_HAS_BEST_LAP = 1;

// One racer at the snapshot's moment, as the launcher's race page shows it (Online.Protocol RacerLive): from the
// racer's block and progress record. Times in milliseconds, speeds km/h, the position in the course's units.
struct Racer
{
  std::uint8_t seat = 0;
  RacerState state{};
  std::uint8_t rank = 0;  // the game's ranking byte (progress +0x115), not the race position
  std::uint8_t flags = 0;
  std::uint16_t lap = 0;  // laps completed
  std::uint16_t kos = 0;  // machines this racer knocked out
  std::uint16_t max_energy = 0;
  std::uint16_t pad = 0;
  std::uint32_t lap_ms = 0;  // the current lap's time
  std::uint32_t total_ms = 0;  // the race time so far; the finish time once finished
  std::uint32_t best_lap_ms = 0;  // the best lap, when Flags has HasBestLap
  float speed = 0;
  float energy = 0;
  float top_speed = 0;
  float x = 0;
  float y = 0;
  float z = 0;
  float distance = 0;  // distance covered over all laps (progress +0xF8): what orders the racers still racing
};

// One event of the ring. Seq is 2 * (its number + 1) once written, odd while it is written.
struct Event
{
  std::uint32_t seq = 0;
  EventKind kind{};
  std::uint32_t beat = 0;  // the heartbeat (low 32 bits) when it was written
  std::uint32_t step = 0;  // the race's step then, or 0
  std::uint32_t a = 0;
  std::uint32_t b = 0;
  std::uint32_t ms = 0;  // milliseconds since the game took the board
  std::uint32_t pad = 0;
};

// Where the game is, written when it changes.
struct Status
{
  Phase phase{};
  std::uint32_t flags = 0;
  std::uint32_t step = 0;  // the race's step at the last displayed frame
  std::uint32_t stop_seen = 0;  // the mailbox's StopSerial the game has acted on
  std::uint32_t notice_seen = 0;  // the mailbox's NoticeSerial the game has taken
};

// The race as this game simulates it, every displayed frame of a race (not a replay): the launcher's race page and the
// lobby's watchers. Rollback can correct the other racers' numbers a moment later. Picture only: nothing of the race
// reads it.
struct Snapshot
{
  std::uint32_t serial = 0;  // snapshots written so far (0: none yet)
  std::uint32_t frame = 0;  // the race's step
  std::uint32_t local_seat = 0;
  std::uint32_t count = 0;  // racers that follow (at most 30)
  std::array<Racer, 30> racers{};
};

// The launcher's words to the game, which it reads once a frame. StopSerial: one more asks for a graceful stop (the
// game stops as when its window closes, says so in its log, and ends with exit code 0). NoticeSerial: one more is a new
// notice, NoticeText's first NoticeLength bytes (UTF-8): the game writes it to its log (showing it in the game is for
// later).
struct Mailbox
{
  std::uint32_t stop_serial = 0;
  std::uint32_t notice_serial = 0;
  std::uint32_t notice_length = 0;
  std::array<std::uint8_t, 128> notice_text{};
};

